drop function if exists api.query_embedding_cache_get(text,text,text);
drop function if exists api.query_embedding_cache_put(text,text,text,extensions.vector,integer);
drop function if exists api.vector_candidates(extensions.vector,text,character,text,integer);
drop index if exists search.course_embeddings_hnsw_idx;
alter table search.course_embeddings alter column embedding type extensions.vector(384) using null::extensions.vector(384), alter column dimensions set default 384;
alter table search.course_embeddings add column if not exists model_version text;
update search.course_embeddings set model_version='unversioned' where model_version is null;
alter table search.course_embeddings alter column model_version set not null;
alter table search.query_embedding_cache alter column embedding type extensions.vector(384) using null::extensions.vector(384);
alter table search.query_embedding_cache add column if not exists model_version text;
update search.query_embedding_cache set model_version='unversioned' where model_version is null;
alter table search.query_embedding_cache alter column model_version set not null;
alter table search.embedding_jobs add column if not exists model_version text;
create index course_embeddings_hnsw_idx on search.course_embeddings using hnsw (embedding extensions.vector_cosine_ops);
create index if not exists course_embeddings_freshness_idx on search.course_embeddings(profile_id,model_name,model_version,content_hash);
update search.profiles set config=jsonb_set(config,'{embedding}',jsonb_build_object('model_name','Supabase/gte-small','model_version','edge-runtime-gte-small-v1','dimensions',384,'distance','cosine','mean_pool',true,'normalize',true,'semantic_input','search_text-v1','content_hash','semantic_content_hash'),true),updated_at=now() where code in ('website-default','zoho-default');
create table if not exists search.vector_gate_runs (id uuid primary key default extensions.gen_random_uuid(),gate_code text not null default 'M1-SEARCH-VECTOR',profile_code text not null,model_name text not null,model_version text not null,dimensions integer not null,model_fingerprint text,source_document_count integer,fresh_embedding_count integer,stale_embedding_count integer,status text not null default 'running',metrics jsonb not null default '{}'::jsonb,started_at timestamptz not null default now(),completed_at timestamptz,constraint vector_gate_runs_status_ck check(status in ('running','passed','rejected','failed')));
alter table search.vector_gate_runs enable row level security;
revoke all on search.vector_gate_runs from public,anon,authenticated;
grant select,insert,update,delete on search.vector_gate_runs to service_role;
create or replace function api.svc_embedding_pending_v1(p_profile_code text,p_model_name text,p_model_version text,p_limit integer default 100) returns table(course_id uuid,semantic_content_hash text,semantic_text text) language sql stable security definer set search_path=api,search as $$ select d.course_id,d.semantic_content_hash,d.search_text from search.course_documents d join search.profiles p on p.code=p_profile_code and p.status='active' left join search.course_embeddings e on e.course_id=d.course_id and e.profile_id=p.id and e.model_name=p_model_name where e.course_id is null or e.content_hash is distinct from d.semantic_content_hash or e.model_version is distinct from p_model_version or e.dimensions<>384 order by d.course_id limit least(greatest(coalesce(p_limit,100),1),500) $$;
create or replace function api.svc_embedding_upsert_batch_v1(p_profile_code text,p_model_name text,p_model_version text,p_dimensions integer,p_records jsonb) returns integer language plpgsql security definer set search_path=api,search,extensions as $$ declare v_profile_id uuid;v_count integer; begin if p_dimensions<>384 then raise exception 'dimensions must be 384'; end if; select id into v_profile_id from search.profiles where code=p_profile_code and status='active'; if v_profile_id is null then raise exception 'active profile not found'; end if; insert into search.course_embeddings(course_id,profile_id,model_name,model_version,dimensions,embedding,content_hash,embedded_at) select x.course_id,v_profile_id,p_model_name,p_model_version,384,x.embedding::extensions.vector(384),x.content_hash,now() from jsonb_to_recordset(coalesce(p_records,'[]'::jsonb)) as x(course_id uuid,content_hash text,embedding text) join search.course_documents d on d.course_id=x.course_id and d.semantic_content_hash=x.content_hash on conflict(course_id,profile_id,model_name) do update set model_version=excluded.model_version,dimensions=excluded.dimensions,embedding=excluded.embedding,content_hash=excluded.content_hash,embedded_at=excluded.embedded_at; get diagnostics v_count=row_count; return v_count; end $$;
create or replace function api.svc_embedding_clone_profile_v1(p_source_profile_code text,p_target_profile_code text,p_model_name text,p_model_version text) returns integer language plpgsql security definer set search_path=api,search as $$ declare v_source uuid;v_target uuid;v_count integer; begin select id into v_source from search.profiles where code=p_source_profile_code and status='active'; select id into v_target from search.profiles where code=p_target_profile_code and status='active'; if v_source is null or v_target is null then raise exception 'active profile not found'; end if; insert into search.course_embeddings(course_id,profile_id,model_name,model_version,dimensions,embedding,content_hash,embedded_at) select course_id,v_target,model_name,model_version,dimensions,embedding,content_hash,now() from search.course_embeddings where profile_id=v_source and model_name=p_model_name and model_version=p_model_version on conflict(course_id,profile_id,model_name) do update set model_version=excluded.model_version,dimensions=excluded.dimensions,embedding=excluded.embedding,content_hash=excluded.content_hash,embedded_at=excluded.embedded_at; get diagnostics v_count=row_count; return v_count; end $$;
create or replace function api.svc_query_embedding_cache_get_v1(p_cache_key text,p_model_name text,p_model_version text,p_profile_version text) returns table(embedding extensions.vector(384),hit_count bigint) language plpgsql security definer set search_path=api,search,extensions as $$ begin update search.query_embedding_cache q set last_used_at=now(),hit_count=q.hit_count+1 where q.cache_key=p_cache_key and q.model_name=p_model_name and q.model_version=p_model_version and q.profile_version=p_profile_version and q.expires_at>now(); return query select q.embedding,q.hit_count from search.query_embedding_cache q where q.cache_key=p_cache_key and q.model_name=p_model_name and q.model_version=p_model_version and q.profile_version=p_profile_version and q.expires_at>now(); end $$;
create or replace function api.svc_query_embedding_cache_put_v1(p_cache_key text,p_model_name text,p_model_version text,p_profile_version text,p_embedding extensions.vector(384),p_ttl_seconds integer default 604800) returns void language sql security definer set search_path=api,search,extensions as $$ insert into search.query_embedding_cache(cache_key,model_name,model_version,profile_version,embedding,expires_at) values(p_cache_key,p_model_name,p_model_version,p_profile_version,p_embedding,now()+make_interval(secs=>least(greatest(coalesce(p_ttl_seconds,604800),60),2592000))) on conflict(cache_key) do update set model_name=excluded.model_name,model_version=excluded.model_version,profile_version=excluded.profile_version,embedding=excluded.embedding,created_at=now(),last_used_at=now(),hit_count=0,expires_at=excluded.expires_at $$;
create or replace function api.svc_vector_candidates_v1(p_embedding extensions.vector(384),p_profile_code text default 'website-default',p_country_codes text[] default null,p_subdivision_codes text[] default null,p_level_codes text[] default null,p_field_codes text[] default null,p_delivery_modes text[] default null,p_limit integer default 20) returns table(course_id uuid,course_title text,provider_name text,country_code text,study_level_code text,primary_field_code text,distance double precision) language sql stable security definer set search_path=api,search,extensions as $$ select d.course_id,d.course_title,d.provider_name,d.country_code,d.study_level_code,d.primary_field_code,(e.embedding<=>p_embedding)::double precision from search.course_embeddings e join search.profiles p on p.id=e.profile_id and p.code=p_profile_code and p.status='active' join search.course_documents d on d.course_id=e.course_id and d.semantic_content_hash=e.content_hash where (p_country_codes is null or d.country_code=any(p_country_codes)) and (p_subdivision_codes is null or d.subdivision_codes&&p_subdivision_codes) and (p_level_codes is null or d.study_level_code=any(p_level_codes)) and (p_field_codes is null or d.primary_field_code=any(p_field_codes)) and (p_delivery_modes is null or d.delivery_modes&&p_delivery_modes) order by e.embedding<=>p_embedding limit least(greatest(coalesce(p_limit,20),1),100) $$;
create or replace function api.svc_fts_candidates_v1(p_query text,p_country_codes text[] default null,p_subdivision_codes text[] default null,p_level_codes text[] default null,p_field_codes text[] default null,p_delivery_modes text[] default null,p_limit integer default 20) returns table(course_id uuid,course_title text,provider_name text,country_code text,study_level_code text,primary_field_code text,score real) language sql stable security definer set search_path=api,search as $$ with q as(select websearch_to_tsquery('english',coalesce(p_query,'')) tsq) select d.course_id,d.course_title,d.provider_name,d.country_code,d.study_level_code,d.primary_field_code,ts_rank_cd(d.search_tsv,q.tsq)::real from search.course_documents d cross join q where d.search_tsv@@q.tsq and (p_country_codes is null or d.country_code=any(p_country_codes)) and (p_subdivision_codes is null or d.subdivision_codes&&p_subdivision_codes) and (p_level_codes is null or d.study_level_code=any(p_level_codes)) and (p_field_codes is null or d.primary_field_code=any(p_field_codes)) and (p_delivery_modes is null or d.delivery_modes&&p_delivery_modes) order by ts_rank_cd(d.search_tsv,q.tsq) desc,d.course_title,d.course_id limit least(greatest(coalesce(p_limit,20),1),100) $$;
create or replace function api.svc_hybrid_candidates_v1(p_query text,p_embedding extensions.vector(384),p_profile_code text default 'website-default',p_country_codes text[] default null,p_subdivision_codes text[] default null,p_level_codes text[] default null,p_field_codes text[] default null,p_delivery_modes text[] default null,p_limit integer default 20) returns table(course_id uuid,course_title text,provider_name text,country_code text,study_level_code text,primary_field_code text,hybrid_score double precision,fts_rank bigint,vector_rank bigint) language sql stable security definer set search_path=api,search,extensions as $$ with prof as(select id,coalesce((config->>'rrf_k')::double precision,60) rrf_k,coalesce((config->>'fts_weight')::double precision,1) fts_weight,coalesce((config->>'vector_weight')::double precision,0.55) vector_weight from search.profiles where code=p_profile_code and status='active'),q as(select websearch_to_tsquery('english',coalesce(p_query,'')) tsq),fts as(select d.course_id,row_number() over(order by ts_rank_cd(d.search_tsv,q.tsq) desc,d.course_title,d.course_id) rnk from search.course_documents d cross join q where d.search_tsv@@q.tsq and (p_country_codes is null or d.country_code=any(p_country_codes)) and (p_subdivision_codes is null or d.subdivision_codes&&p_subdivision_codes) and (p_level_codes is null or d.study_level_code=any(p_level_codes)) and (p_field_codes is null or d.primary_field_code=any(p_field_codes)) and (p_delivery_modes is null or d.delivery_modes&&p_delivery_modes) order by ts_rank_cd(d.search_tsv,q.tsq) desc,d.course_title,d.course_id limit 100),vec as(select d.course_id,row_number() over(order by e.embedding<=>p_embedding,d.course_id) rnk from search.course_embeddings e join prof on prof.id=e.profile_id join search.course_documents d on d.course_id=e.course_id and d.semantic_content_hash=e.content_hash where (p_country_codes is null or d.country_code=any(p_country_codes)) and (p_subdivision_codes is null or d.subdivision_codes&&p_subdivision_codes) and (p_level_codes is null or d.study_level_code=any(p_level_codes)) and (p_field_codes is null or d.primary_field_code=any(p_field_codes)) and (p_delivery_modes is null or d.delivery_modes&&p_delivery_modes) order by e.embedding<=>p_embedding,d.course_id limit 100),merged as(select coalesce(f.course_id,v.course_id) course_id,f.rnk fts_rank,v.rnk vector_rank from fts f full outer join vec v using(course_id)),scored as(select m.*,coalesce((select fts_weight from prof)/((select rrf_k from prof)+m.fts_rank),0)+coalesce((select vector_weight from prof)/((select rrf_k from prof)+m.vector_rank),0) score from merged m) select d.course_id,d.course_title,d.provider_name,d.country_code,d.study_level_code,d.primary_field_code,s.score,s.fts_rank,s.vector_rank from scored s join search.course_documents d on d.course_id=s.course_id order by s.score desc,d.course_title,d.course_id limit least(greatest(coalesce(p_limit,20),1),100) $$;
